/** "{n} leads" jaise placeholders bharne ke liye */
export function fill(str, vars) {
  return String(str).replace(/\{(\w+)\}/g, (_, k) => (vars[k] != null ? vars[k] : `{${k}}`));
}

const LangCtx = createContext({ lang: 'hinglish', setLang: () => {}, t: (k) => k });
export const useT = () => useContext(LangCtx);

export function LangProvider({ children }) {
  const [lang, setLangState] = useState(() => {
    try { return localStorage.getItem('crm_lang') || 'hinglish'; } catch { return 'hinglish'; }
  });
  const setLang = (l) => {
    setLangState(l);
    try { localStorage.setItem('crm_lang', l); } catch { /* private mode */ }
  };
  useEffect(() => { document.documentElement.lang = lang === 'hi' ? 'hi' : 'en'; }, [lang]);

  const t = (key) => (STR[lang] && STR[lang][key]) || STR.en[key] || key;
  return <LangCtx.Provider value={{ lang, setLang, t }}>{children}</LangCtx.Provider>;
}
